teaching.example:
room=${ROOM:-Exhibit hall}
credit=${CREDIT-Museum staff}
label=${LABEL-Guest label}
provided=${CREDIT+yes}
provided=${provided:-no}
visible=${CREDIT:+yes}
visible=${visible:-no}
printf 'Room: <%s>\nCredit: <%s>\nCredit supplied: %s\nCredit has text: %s\nLabel: <%s>\n' "$room" "$credit" "$provided" "$visible" "$label"

show() {
 chosen=${1-flyer.txt}
 if test -z "$chosen"; then printf 'Choose a flyer\n' >&2; return 2; fi
 case "$chosen" in -|.|..|*/*) printf 'Use a simple flyer filename\n' >&2; return 2 ;; esac
 if test -f "$chosen"; then :; else printf 'Flyer missing\n' >&2; return 2; fi
 printf 'Preview: %s\n' "$chosen"
 cat -- "$chosen"
}
show
